206		sessionTree, err := s.sessionTreeFromMain(ctx, checkpointID, sessionIndex)
207		if err != nil {
208			if ctxErr := ctx.Err(); ctxErr != nil {
209				return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
210			}
211			return nil, ErrCheckpointNotFound
212		}
213	
214		result := &SessionContent{}
215		sessionFT := s.wrapWithFetcher(ctx, sessionTree)
216	
217		if metadataFile, fileErr := sessionFT.File(paths.MetadataFileName); fileErr == nil {
218			if content, contentErr := metadataFile.Contents(); contentErr == nil {
219				if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
220					return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
221				}
222			}
223		}
224	
225		if file, fileErr := sessionFT.File(paths.PromptFileName); fileErr == nil {
226			if content, contentErr := file.Contents(); contentErr == nil {
227				result.Prompts = content
228			}
229		}
230	
